package com.loopers.application.product;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.client.TestRestTemplate;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.jdbc.Sql;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) @Sql("classpath:week4/product-query-seed.sql") class ProductQueryE2ETest{@Autowired ProductQueryService service;@Autowired JdbcTemplate db;@Autowired TestRestTemplate http;
 @Test void fixedSeedAndOrderedResultAreStable(){assertThat(db.queryForObject("select count(*) from products",Long.class)).isEqualTo(10000);assertThat(db.queryForObject("select sum(price) from products",Long.class)).isEqualTo(472685000);assertThat(db.queryForObject("select count(*) from products where brand_id=7",Long.class)).isEqualTo(100);assertThat(db.queryForObject("select sum(price) from products where brand_id=7",Long.class)).isEqualTo(4647200);List<ProductQueryService.Result> first=service.find(7,20),second=service.find(7,20);assertThat(first).hasSize(20).isEqualTo(second).isSortedAccordingTo(Comparator.comparingLong(ProductQueryService.Result::price).thenComparingLong(ProductQueryService.Result::id));assertThat(http.getForEntity("/api/v1/products?brandId=7&sort=price_asc&limit=20",String.class).getStatusCode().is2xxSuccessful()).isTrue();db.update("update products set price=0 where id=?",first.getFirst().id());service.priceChanged(7);assertThat(service.find(7,20).getFirst().price()).isZero();}}
